<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import SearchSelect, { type SearchOption } from './SearchSelect.vue'
import WeaponSelect from './WeaponSelect.vue'
import RivenCardPreview from './RivenCardPreview.vue'
import { useCatalogStore } from '../stores/catalog'
import { tauriAvailable, type RivenAttribute, type RivenWeapon } from '../api/market'
import { fetchRerollOptions, planReroll, type RerollAttribute, type RerollOptionsResult, type RerollPlanRequest, type RerollPlanResult } from '../api/reroll'
import { weaponOptionsFor, type WeaponOption } from '../ui/weaponOptions'
import { attributePresentation, sortAttributePresentation } from '../ui/attributePresentation'

type Row = RerollAttribute & { id: number; valueText: string; fused: boolean }
type Slot = { id: number; attrs: string[]; minW: string; minValue: string }
const catalog = useCatalogStore(); const weapon = ref(''); const modRank = ref('8'); const ruleMode = ref<'current'|'legacy'>('current'); const disposition = ref(''); const rerolls = ref('0'); const kuva = ref(''); const optimize = ref<'kuva'|'cycles'>('kuva')
const positives = ref<Row[]>([]); const negatives = ref<Row[]>([]); const newPositives = ref<Row[]>([]); const newNegatives = ref<Row[]>([]); const newCardEnabled = ref(false); const goals = ref<Array<{id:number; slots:Slot[]; allowLayout:boolean; allowNegative:boolean}>>([])
const layouts = ref<string[]>(['20','21','30','31']); const allowedNegatives = ref<string[]|null>(null); const atLeastEnabled = ref(false); const atLeastK = ref(''); const atLeastW = ref('0.9')
const result = ref<RerollPlanResult|null>(null); const stale = ref(false); const selectedRoute = ref(0); const error = ref(''); const loading = ref(false); const generation = ref(0); let nextId = 1; let alive = true
const rerollOptions = ref<RerollOptionsResult|null>(null); const optionsLoading = ref(false); const optionsError = ref(''); let optionsGeneration = 0
const weapons = computed<RivenWeapon[]>(() => catalog.catalog?.weapons ?? []); const attrs = computed<RivenAttribute[]>(() => catalog.catalog?.attributes ?? []); const weaponOptions = computed<WeaponOption[]>(() => weaponOptionsFor(weapons.value)); const selectedWeapon = computed(() => weapons.value.find(item => item.slug === weapon.value));
const attrMap = computed(() => new Map(attrs.value.map(a => [a.slug, a]))); const name = (slug:string) => attrMap.value.get(slug)?.name ?? slug
const optionBySlug = computed(() => new Map(attrs.value.map(a => [a.slug, a])))
function optionList(slugs:string[]) { return sortAttributePresentation(slugs.map(slug => optionBySlug.value.get(slug)).filter((a): a is RivenAttribute => Boolean(a))).map(a => ({ value:a.slug, label:a.name, secondary:a.english_name, group:attributePresentation(a).group })) }
const options = computed<SearchOption[]>(() => optionList([...new Set([...(rerollOptions.value?.positive ?? []), ...(rerollOptions.value?.spliced ?? [])])]))
const negativeOptions = computed<SearchOption[]>(() => optionList(rerollOptions.value?.negative.filter(slug => !rerollOptions.value?.spliced.includes(slug)) ?? []))
const validRows = computed(() => Boolean(weapon.value) && /^(?:[0-8])$/.test(modRank.value) && cardValid(positives.value, negatives.value) && Number.isInteger(Number(rerolls.value)) && Number(rerolls.value)>=0 && (!kuva.value.trim() || (Number.isInteger(Number(kuva.value)) && Number(kuva.value)>=0)) && layouts.value.length > 0)
const numeric = (v:string) => /^[-+]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(v.trim()) && Number.isFinite(Number(v))
const cardValid = (p:Row[], n:Row[]) => p.length>=2 && p.length<=3 && p.every(r=>r.slug&&numeric(r.valueText)) && n.length<=1 && n.every(r=>r.slug&&numeric(r.valueText) && attributePresentation(attrMap.value.get(r.slug) ?? {slug:r.slug,name:r.slug}).group !== '熔接') && new Set([...p,...n].map(r=>r.slug).filter(Boolean)).size===p.length+n.length && [...p,...n].filter(r=>r.fused).length<=1
const canPlan = computed(() => Boolean(rerollOptions.value?.positive.length || rerollOptions.value?.negative.length) && validRows.value && (ruleMode.value!=='legacy' || (numeric(disposition.value) && Number(disposition.value)>=0.5 && Number(disposition.value)<=1.55)) && (!newCardEnabled.value || cardValid(newPositives.value,newNegatives.value)) && goals.value.length > 0 && goals.value.every(g => g.slots.length > 0 && g.slots.every(s=>s.attrs.length > 0 && Number.isFinite(Number(s.minW)) && Number(s.minW)>=0.9 && Number(s.minW)<=1.1 && (!s.minValue.trim() || numeric(s.minValue)))))
function addRow(kind:'positive'|'negative', isNew=false) { const target=kind==='positive'?(isNew?newPositives:positives):(isNew?newNegatives:negatives); if ((kind==='positive'&&target.value.length>=3)||(kind==='negative'&&target.value.length>=1)) return; target.value.push({id:nextId++,slug:'',value:0,positive:kind==='positive',spliced:false,valueText:'',fused:false}) }
function removeRow(kind:'positive'|'negative', index:number) { (kind==='positive'?positives:negatives).value.splice(index,1) }
function toggleSpliced(row: Row) { if (row.positive && attributePresentation(attrMap.value.get(row.slug) ?? {slug:row.slug,name:row.slug}).group !== '熔接') return; if (!row.fused && [...positives.value, ...negatives.value].some(item => item !== row && item.fused)) return; row.fused = !row.fused }
function isSplicedRow(row: Row) { return row.fused || Boolean(row.slug && attributePresentation(attrMap.value.get(row.slug) ?? {slug:row.slug,name:row.slug}).group === '熔接') }
function compareSuggestion() { if (!result.value || stale.value || !newCardEnabled.value) return ''; const oldValue=result.value.current_value, nextValue=result.value.compare_values?.[0]; if (nextValue==null) return '新卡不可达，保留旧卡'; if (oldValue==null) return '新卡可达，建议保留新卡'; return nextValue < oldValue ? '新卡预计成本更低，建议保留新卡' : nextValue > oldValue ? '旧卡预计成本更低，建议保留旧卡' : '两张卡预计成本相同，可保留词条更合适者' }
async function recordCycle(chosen:'old'|'new') { if (stale.value || !result.value || !newCardEnabled.value) return; const selected=result.value.routes[selectedRoute.value]; const action=selected?.route.action; if (!selected || action?.kind==='splice' || !Number.isFinite(selected.next_cycle_cost)) { error.value='请先重新规划以获得本次循环成本。'; return } if (chosen==='new') { positives.value=newPositives.value.map(r=>({...r,id:nextId++})); negatives.value=newNegatives.value.map(r=>({...r,id:nextId++})) } kuva.value=kuva.value.trim()?String(Math.max(0,Number(kuva.value)-selected.next_cycle_cost)):''; rerolls.value=String(Number(rerolls.value||0)+1); newCardEnabled.value=false; await nextTick(); void submit() }
function applyNewCard() { recordCycle('new') }
async function confirmSplice() { if (stale.value || !newCardEnabled.value || !selectedIsSplice() || !cardValid(newPositives.value,newNegatives.value)) return; positives.value=newPositives.value.map(r=>({...r,id:nextId++})); negatives.value=newNegatives.value.map(r=>({...r,id:nextId++})); newCardEnabled.value=false; await nextTick(); void submit() }
function statNames(values:string[]) { return values.map(name).join(' / ') }
function routeAction(route:RerollPlanResult['routes'][number]) { const a=route.route.action; if(a.kind==='splice') return `熔接 ${name(a.a)} + ${name(a.b)} → ${name(a.result)}`; if(a.lock==='none') return a.drop?'循环：不锁定（解除熔接锁）':'循环：不锁定'; if(a.lock==='neg') return '循环：锁定负面'; return `循环：锁定 ${statNames(a.lock.stats)}${a.drop?'（解除熔接锁）':''}` }
function selectedIsSplice() { return result.value?.routes[selectedRoute.value]?.route.action.kind === 'splice' }
function addGoal() { goals.value.push({id:nextId++, slots:[{id:nextId++,attrs:[],minW:'0.9',minValue:''}],allowLayout:true,allowNegative:true}) }
async function refreshOptions() { const token=++optionsGeneration; if (!weapon.value || !tauriAvailable) { rerollOptions.value=null; optionsLoading.value=false; return } optionsLoading.value=true; optionsError.value=''; try { const seen=new Map<string,Row>(); [...positives.value,...negatives.value,...newPositives.value,...newNegatives.value].filter(r=>r.slug).forEach(r=>seen.set(r.slug,r)); const value=await fetchRerollOptions({weapon_slug:weapon.value,current_attributes:attrsFor([...seen.values()])}); if (token===optionsGeneration) rerollOptions.value=value } catch (cause) { if (token===optionsGeneration) { rerollOptions.value=null; optionsError.value=errText(cause) } } finally { if (token===optionsGeneration) optionsLoading.value=false } }
function addSlot(goal:{slots:Slot[]}) { goal.slots.push({id:nextId++,attrs:[],minW:'0.9',minValue:''}) }
function attrsFor(rows: Row[]) { return rows.filter(r=>r.slug).map(r=>({slug:r.slug,value:numeric(r.valueText)?Number(r.valueText):0,positive:r.positive,spliced:Boolean(r.positive && attributePresentation(attrMap.value.get(r.slug) ?? {slug:r.slug,name:r.slug}).group === '熔接')})) }
function request(): RerollPlanRequest { const groups=goals.value.flatMap(g=>g.slots.map(s=>({slugs:s.attrs,min_w:Number(s.minW||0.9),min_values:s.minValue.trim()?Object.fromEntries(s.attrs.map(slug=>[slug,Number(s.minValue)])):null}))); let offset=0; const sets=goals.value.map(g=>g.slots.map(()=>offset++)); const layoutsValue=layouts.value.map(v=>({pos:Number(v[0]) as 2|3,neg:Number(v[1]) as 0|1})); return { weapon_slug:weapon.value, mod_rank:Number(modRank.value), rule_mode:ruleMode.value, disposition:ruleMode.value==='legacy'?Number(disposition.value||selectedWeapon.value?.disposition):null, current_attributes:attrsFor([...positives.value,...negatives.value]), rerolls:Number(rerolls.value||0), kuva_budget:kuva.value.trim()?Number(kuva.value):null, objective:optimize.value, target:{groups,sets:sets.length>1?sets:null,layouts:layoutsValue,allowed_negatives:layoutsValue.every(item=>item.neg===0)?[]:(allowedNegatives.value?.length?allowedNegatives.value:null),at_least:atLeastEnabled.value?{k:Number(atLeastK.value),w:Number(atLeastW.value)}:null}, new_attributes:newCardEnabled.value?attrsFor([...newPositives.value,...newNegatives.value]):null } }
function errText(e:unknown) { return typeof e==='string'?e:e instanceof Error?e.message:'洗卡规划失败。' }
async function submit() { if(!canPlan.value||loading.value)return; if(!tauriAvailable){error.value='请在 WM Market 桌面应用中进行规划。';return} const token=++generation.value; loading.value=true; error.value=''; try { const value=await planReroll(request()); if(value.ok===false) throw new Error(value.error || '洗卡规划失败。'); if(alive&&token===generation.value) { result.value=value; stale.value=false; selectedRoute.value=0 } } catch(e) { if(alive&&token===generation.value) error.value=errText(e) } finally { if(alive) loading.value=false } }
function resetResult(){generation.value++;error.value='';if(result.value) stale.value=true}
function resultEntries() { return result.value ? Object.entries(result.value).filter(([,v])=>v!==null&&v!==undefined&&typeof v!=='object') : [] }
watch([weapon,modRank,ruleMode,disposition,rerolls,kuva,positives,negatives,newPositives,newNegatives,newCardEnabled,goals,optimize,layouts,allowedNegatives,atLeastEnabled,atLeastK,atLeastW],resetResult,{deep:true}); watch(selectedWeapon,w=>{if(ruleMode.value==='legacy'&&w?.disposition!=null) disposition.value=String(w.disposition)})
watch([weapon, () => positives.value.map(r=>r.slug), () => negatives.value.map(r=>r.slug), () => newPositives.value.map(r=>r.slug), () => newNegatives.value.map(r=>r.slug)], () => void refreshOptions(), { deep:true })
watch(allowedNegatives, value => { if (Array.isArray(value) && value.length === 0) allowedNegatives.value = null })
watch([positives,newPositives], ([...lists]) => lists.forEach((rows:any) => rows.forEach((row:Row) => { row.fused = Boolean(row.slug && row.positive && attributePresentation(attrMap.value.get(row.slug) ?? {slug:row.slug,name:row.slug}).group === '熔接') })), { deep: true })
onMounted(()=>{void catalog.load()}); onUnmounted(()=>{alive=false;generation.value++})
</script>

<template>
  <section class="reroll-page" aria-labelledby="reroll-title">
    <header class="reroll-heading"><div><h1 id="reroll-title">紫卡洗卡指导</h1><p class="page-description">输入当前紫卡与目标组合，规划可执行的洗卡路线。</p></div><span class="status-chip"><span class="status-dot" aria-hidden="true" />{{ loading ? '后台计算中' : result ? '已完成' : '待规划' }}</span></header>
    <form class="reroll-layout" @submit.prevent="submit">
      <div class="reroll-form">
        <section v-if="newCardEnabled" class="reroll-panel"><div class="panel-title-row"><h2>下一轮新卡</h2><button type="button" class="text-button" @click="newCardEnabled=false">取消</button></div><p class="panel-help">输入循环后新卡，与当前卡比较后可保留并重算。</p><div class="reroll-subheading">正面词条</div><div v-for="(row,i) in newPositives" :key="row.id" class="reroll-stat-row"><SearchSelect v-model="row.slug" :options="options" grouped :label="`新卡正面词条${i+1}`" :input-id="`reroll-new-positive-${row.id}`" placeholder="选择词条" /><input v-model="row.valueText" inputmode="decimal" placeholder="显示值" /><button type="button" class="text-button" @click="newPositives.splice(i,1)">移除</button></div><button v-if="newPositives.length<3" type="button" class="secondary-button" @click="addRow('positive',true)">添加正面</button><div class="reroll-subheading">负面词条</div><div v-for="(row,i) in newNegatives" :key="row.id" class="reroll-stat-row"><SearchSelect v-model="row.slug" :options="negativeOptions" grouped :label="`新卡负面词条${i+1}`" :input-id="`reroll-new-negative-${row.id}`" placeholder="选择词条" /><input v-model="row.valueText" inputmode="decimal" placeholder="显示值" /><button type="button" class="text-button" @click="newNegatives.splice(i,1)">移除</button></div><button v-if="!newNegatives.length" type="button" class="secondary-button" @click="addRow('negative',true)">添加负面</button></section>
        <section class="reroll-panel"><h2>当前紫卡</h2><div class="reroll-grid"><WeaponSelect v-model="weapon" :options="weaponOptions" label="武器" input-id="reroll-weapon" placeholder="选择武器" /><label class="filter-field">强化等级<select v-model="modRank"><option v-for="n in 9" :key="n" :value="String(n-1)">强化 {{ n-1 }}</option></select></label><label class="filter-field">规则<select v-model="ruleMode"><option value="current">现行规则 D1.2</option><option value="legacy">Legacy / 历史倍率</option></select></label><label v-if="ruleMode==='legacy'" class="filter-field">Legacy D 值<input v-model="disposition" inputmode="decimal" placeholder="武器默认" /></label></div><div class="reroll-stat-groups"><div><div class="reroll-subheading">正面词条 <small>2–3 个</small></div><div v-for="(row,i) in positives" :key="row.id" class="reroll-stat-row"><SearchSelect v-model="row.slug" :options="options" grouped :label="`正面词条${i+1}`" :input-id="`reroll-positive-${row.id}`" placeholder="选择词条" /><input v-model="row.valueText" inputmode="decimal" placeholder="显示值" :aria-label="`正面词条${i+1}数值`" /><span v-if="isSplicedRow(row)" class="reroll-fuse active">已熔接</span><button type="button" class="text-button" @click="removeRow('positive',i)">移除</button></div><button v-if="positives.length<3" type="button" class="secondary-button" @click="addRow('positive')">添加正面</button></div><div><div class="reroll-subheading">负面词条 <small>0–1 个</small></div><div v-for="(row,i) in negatives" :key="row.id" class="reroll-stat-row"><SearchSelect v-model="row.slug" :options="negativeOptions" grouped :label="`负面词条${i+1}`" :input-id="`reroll-negative-${row.id}`" placeholder="选择词条" /><input v-model="row.valueText" inputmode="decimal" placeholder="显示值" :aria-label="`负面词条${i+1}数值`" /><span v-if="isSplicedRow(row)" class="reroll-fuse active">已熔接</span><button type="button" class="text-button" @click="removeRow('negative',i)">移除</button></div><button v-if="!negatives.length" type="button" class="secondary-button" @click="addRow('negative')">添加负面</button></div></div><div class="reroll-grid"><label class="filter-field">已洗次数<input v-model="rerolls" inputmode="numeric" min="0" /></label><label class="filter-field">可用赤毒<input v-model="kuva" inputmode="numeric" placeholder="不设预算" /></label><label class="filter-field">优化目标<select v-model="optimize"><option value="kuva">优先节省赤毒</option><option value="cycles">优先减少循环次数</option></select></label></div></section>
        <section class="reroll-panel"><div class="panel-title-row"><h2>目标组合</h2><button type="button" class="secondary-button" @click="addGoal">添加 OR 组合</button></div><p class="panel-help">每组可配置多个目标槽；同一槽内词条为 OR 条件。W 为最低理论品质，显示值会应用到该槽全部词条。</p><article v-for="(goal,gi) in goals" :key="goal.id" class="goal-card"><div class="goal-title"><strong>组合 {{ gi+1 }}</strong><button type="button" class="text-button" @click="goals.splice(gi,1)">移除组合</button></div><div v-for="(slot,si) in goal.slots" :key="slot.id" class="goal-slot"><span class="slot-label">目标槽 {{ si+1 }}</span><SearchSelect v-model="slot.attrs" :options="options" grouped multiple :max="4" :label="`组合${gi+1}目标槽${si+1}`" :input-id="`reroll-goal-${slot.id}`" placeholder="选择多个词条 OR" /><input v-model="slot.minW" inputmode="decimal" min="0.9" max="1.1" step="0.01" placeholder="最低 W" aria-label="最低 W" /><input v-model="slot.minValue" inputmode="decimal" placeholder="最低显示值" aria-label="最低显示值" /></div><button type="button" class="text-button" @click="addSlot(goal)">+ 添加目标槽</button></article><p v-if="!goals.length" class="empty-inline">添加至少一组目标组合后开始规划。</p><div class="advanced-target"><strong>高级目标限制</strong><div class="layout-options"><span>允许布局</span><label v-for="layout in ['20','21','30','31']" :key="layout"><input v-model="layouts" type="checkbox" :value="layout" />{{ layout[0] }}正 {{ layout[1] }}负</label></div><label class="filter-field"><span>允许的负面词条（留空不限）</span><SearchSelect v-model="allowedNegatives" :options="negativeOptions" grouped multiple :max="4" label="允许的负面词条" input-id="reroll-allowed-negative" placeholder="不限" /></label><label class="goal-check"><input v-model="atLeastEnabled" type="checkbox" />至少达到指定数量的 W 词条</label><div v-if="atLeastEnabled" class="at-least-fields"><input v-model="atLeastK" inputmode="numeric" placeholder="数量 k" aria-label="W词条数量" /><input v-model="atLeastW" inputmode="decimal" placeholder="W 阈值" aria-label="W阈值" /></div></div></section>
        <button class="primary-button reroll-submit" type="submit" :disabled="!canPlan||loading">{{ loading?'正在规划…':'开始规划' }}</button><p v-if="optionsLoading" class="panel-help">正在加载该武器可用词条…</p><p v-if="optionsError" class="reroll-error" role="alert">{{ optionsError }}</p><p v-else-if="weapon && !optionsLoading && !rerollOptions" class="reroll-error" role="alert">该武器的可用词条暂不可用。</p><p v-if="error" class="reroll-error" role="alert">{{ error }}</p>
      </div>
      <aside class="reroll-side"><div class="reroll-preview"><RivenCardPreview :title="selectedWeapon?.i18n['zh-hans']?.name??selectedWeapon?.i18n.en?.name??'未选择武器'" :subtitle="selectedWeapon?.i18n.en?.name" :positives="positives.map(r=>`${name(r.slug)} ${r.valueText||'—'}`)" :negatives="negatives.map(r=>`${name(r.slug)} ${r.valueText||'—'}`)" /></div><section class="reroll-result"><h2>规划结果</h2><p v-if="loading" class="panel-help">正在计算；上一轮结果仍保留。</p><p v-else-if="!result" class="panel-help">完成输入后开始规划。成功率、预计次数、赤毒、中位数 / p90 与预算完成率将在这里显示。</p><template v-else><div class="result-status">{{ result.done ? '目标已完成' : result.reachable ? '找到可行路线' : '当前目标不可达' }}</div><p v-if="stale" class="reroll-stale">条件已变化，请重新规划</p><p v-if="newCardEnabled" class="compare-advice">{{ compareSuggestion() }} <span><small v-if="selectedIsSplice()">熔接路线不计洗卡；请先确认熔接后的新卡。</small> <button v-if="selectedIsSplice()" type="button" class="secondary-button" :disabled="stale" @click="confirmSplice">确认熔接后紫卡</button> <button type="button" class="secondary-button" :disabled="stale || selectedIsSplice()" @click="recordCycle('old')">保留旧卡并重算</button> <button type="button" class="secondary-button" :disabled="stale || selectedIsSplice()" @click="recordCycle('new')">保留新卡并重算</button> <button type="button" class="text-button" :disabled="stale || selectedIsSplice()" @click="recordCycle('old')">本次未改善</button></span></p><div v-for="(route,index) in result.routes" :key="index" class="route-card" :class="{selected:index===selectedRoute}"><button type="button" class="route-select" :aria-pressed="index===selectedRoute" @click="selectedRoute=index"><span>{{ index===0 ? '推荐路线' : `路线 ${index+1}` }}</span><span v-if="route.route.optimal">优先</span></button><template v-if="index===selectedRoute"><p class="route-action">{{ routeAction(route) }}</p><div class="route-metrics"><span>本步改善概率 {{ (route.route.step_chance*100).toFixed(1) }}%</span><span>预计循环 {{ route.route.step_cycles.toFixed(1) }}（p90 {{ route.route.step_cycles_p90.toFixed(1) }}）</span><span>总循环均值/中位数/p90 {{ route.cycles.mean.toFixed(1) }} / {{ route.cycles.p50.toFixed(1) }} / {{ route.cycles.p90.toFixed(1) }}</span><span>赤毒均值/中位数/p90 {{ route.kuva.mean.toFixed(1) }} / {{ route.kuva.p50.toFixed(1) }} / {{ route.kuva.p90.toFixed(1) }} · 熔接均值 {{ route.splicers.toFixed(1) }}</span><span>预算完成率 {{ route.within_budget==null?'—':`${(route.within_budget*100).toFixed(1)}%` }}</span></div><details><summary>保留条件与谨慎提示</summary><div v-for="(outcome,oi) in route.route.outcomes" :key="`o${oi}`" class="outcome-line">{{ (outcome.prob*100).toFixed(1) }}%：{{ outcome.needs.map(n=>`${statNames(n.stats)} ≥ W${n.min_w}${n.neg ? '（负面）' : ''}`).join('、') || '无额外条件' }}（{{ outcome.layout.pos }}正{{ outcome.layout.neg }}负 · 负面{{ outcome.neg_allowed==null?'不限':outcome.neg_allowed?'允许':'不允许' }}）</div><div v-for="(outcome,oi) in route.route.worse" :key="`w${oi}`" class="outcome-line worse">谨慎：{{ (outcome.prob*100).toFixed(1) }}% · {{ outcome.needs.map(n=>`${statNames(n.stats)} ≥ W${n.min_w}${n.neg ? '（负面）' : ''}`).join('、') || '未满足目标' }}（{{ outcome.layout.pos }}正{{ outcome.layout.neg }}负 · 负面{{ outcome.neg_allowed==null?'不限':outcome.neg_allowed?'允许':'不允许' }}）</div></details></template></div><button type="button" class="secondary-button" :disabled="stale" @click="newCardEnabled=true; if(!newPositives.length) addRow('positive',true)">输入下一轮新卡对比</button></template></section></aside>
    </form>
  </section>
</template>

